<script setup lang="ts">
import {computed,ref} from 'vue'
import {useRouter} from 'vue-router'
import {Plus,Search} from '@lucide/vue'
import PageHeading from '../components/common/PageHeading.vue'
import StatusBadge from '../components/common/StatusBadge.vue'
import {useDemoStore} from '../stores/demo'
import {statusLabels,formatTime} from '../mocks/catalog'
const store=useDemoStore(),router=useRouter(),search=ref(''),status=ref(''),model=ref(''),sort=ref('new')
const rows=computed(()=>store.jobs.filter(j=>(!status.value||j.status===status.value)&&(!model.value||j.model===model.value)&&`${j.name} ${j.id} ${j.dataset}`.toLowerCase().includes(search.value.toLowerCase())).sort((a,b)=>sort.value==='progress'?b.progress-a.progress:sort.value==='old'?a.started.localeCompare(b.started):b.started.localeCompare(a.started)))
</script>
<template><PageHeading title="训练任务" description="管理实验生命周期，追踪每一次策略训练。"><button class="button primary" @click="router.push('/training')"><Plus :size="15"/>新建训练</button></PageHeading><div class="stat-strip"><div v-for="s in ['Running','Pending','Completed','Failed']" :key="s" class="strip-item"><span>{{statusLabels[s as keyof typeof statusLabels]}}</span><strong>{{store.jobs.filter(j=>j.status===s).length}}</strong></div></div><div class="page-toolbar"><input v-model="search" placeholder="搜索任务、ID 或数据集…" aria-label="搜索训练任务"/><select v-model="status" aria-label="筛选状态"><option value="">全部状态</option><option v-for="(label,key) in statusLabels" :key="key" :value="key">{{label}}</option></select><select v-model="model" aria-label="筛选模型"><option value="">全部模型</option><option v-for="m in store.models" :key="m.id">{{m.name}}</option></select><select v-model="sort" aria-label="任务排序"><option value="new">最近启动</option><option value="old">最早启动</option><option value="progress">进度从高到低</option></select></div><section class="panel page-table"><table><thead><tr><th>任务 / ID</th><th>模型 / 数据集</th><th>状态</th><th>进度</th><th>开始时间</th><th>运行时长</th><th>GPU</th><th>操作</th></tr></thead><tbody><tr v-for="job in rows" :key="job.id"><td><button class="text-link" @click="router.push('/jobs/'+job.id)">{{job.name}}</button><div class="table-sub">{{job.id}}</div></td><td>{{job.model}}<div class="table-sub">{{job.dataset}}</div></td><td><StatusBadge :status="job.status"/></td><td><div class="table-progress">{{job.progress}}%<div class="progress-track"><div :style="{width:job.progress+'%'}"></div></div></div></td><td>{{job.started}}</td><td class="mono">{{formatTime(job.elapsed)}}</td><td>{{job.gpu}}</td><td><div class="row-actions"><button class="text-link" @click="router.push('/jobs/'+job.id)">监控</button><button v-if="['Running','Pending'].includes(job.status)" class="text-link" @click="store.stop(job.id)">停止</button></div></td></tr></tbody></table><div v-if="!rows.length" class="empty-state">没有符合条件的任务。<br><button class="button" @click="search='';status='';model=''">清除筛选</button></div><div class="panel-foot">共 {{rows.length}} 个任务 · Mock<span class="push-right">模拟运行时长</span></div></section></template>
